{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles Just Cause for Eviction Ordinance","requirement":"A landlord may not terminate a tenancy without just cause and must pay relocation assistance for no-fault evictions such as owner move-in, demolition or government order to vacate. Eviction notices must be filed with LAHD within three business days of service.","key_value":null,"coverage_conditions":"Most residential properties in the City of Los Angeles that are not regulated by the Rent Stabilization Ordinance; for a tenancy to be covered, the tenant must have lived in the unit at least six months or the original lease must have expired, whichever comes first.","applicability":{"conditions":[{"type":"other","text":"Most residential properties in the City of Los Angeles not regulated by the City’s Rent Stabilization Ordinance"}],"per_tenancy":"Tenant must have lived in the same unit at least six months or the original lease must have expired, whichever comes first.","coverage_quotes":["The JCO covers most residential properties in the City of Los Angeles that are not regulated by the City’s Rent Stabilization Ordinance (RSO).","In order to apply to a tenancy, it requires that the tenant either has lived in the same unit for at least six months or that their original lease expired, whichever comes first."]},"exemptions":"Transient hotels, licensed care facilities, fraternity or sorority houses, owner’s roommate, cooperatives under certain circumstances, some non-profit facilities for the homeless or short-term treatment centers for substance abuse, and some properties owned by HACLA or the government.","penalty":null,"effective_date":null,"valid_through":null,"citation":"Los Angeles Just Cause Ordinance (L.A.M.C. §165.00 et seq.)","quoted_span":"It prohibits terminations of tenancies without just cause and requires relocation assistance for no-fault evictions.","interaction":"The JCO does not regulate rent increases; state law AB 1482 may regulate rent amounts in buildings older than 15 years.","relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"Los Angeles, CA","category":"just_cause_eviction","lifecycle":"enacted","title":"Los Angeles non-payment of rent eviction threshold (Fair Market Rent)","requirement":"A landlord may not evict a tenant who falls behind in rent unless the tenant owes an amount higher than the Fair Market Rent for the unit’s bedroom size. This applies to all RSO and JCO rental units.","key_value":"rent owed must exceed the Fair Market Rent","coverage_conditions":"Applies to all RSO and JCO rental units in the City of Los Angeles.","applicability":{"conditions":[{"type":"other","text":"Applies to all RSO and JCO rental units in the City of Los Angeles"}],"per_tenancy":null,"coverage_quotes":["Applies to all RSO & JCO rental units. Effective March 27, 2023, landlords may not evict a tenant who falls behind in rent unless the tenant owes an amount higher than the Fair Market Rent (FMR)."]},"exemptions":null,"penalty":null,"effective_date":"2023-03-27","valid_through":null,"citation":"Evictions for Non-Payment of Rent (City of Los Angeles)","quoted_span":"Effective March 27, 2023, landlords may not evict a tenant who falls behind in rent unless the tenant owes an amount higher than the Fair Market Rent (FMR).","interaction":null,"relations":[],"confidence":0.75,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D040-01","doc_id":"D040","jurisdiction":"CA","category":"rent_increase_limits","lifecycle":"enacted","title":"California Tenant Protection Act of 2019 (AB 1482) rent cap","requirement":"Annual rent increases for covered units are limited to 5% plus the regional cost-of-living change, or 10%, whichever is lower. The maximum allowable increase was 8.9% from August 1, 2024 to July 31, 2025.","key_value":"5% + CPI, max 10%; 8.9% from Aug 1, 2024 to Jul 31, 2025","coverage_conditions":"Buildings older than 15 years, with a rolling 15-year exemption for newly constructed units; exempt also are deed-restricted affordable units, certain dormitories, owner-occupied two-unit properties, and units subject to the City’s RSO.","applicability":{"conditions":[{"type":"built_within_years","role":"exempt","years":15,"basis":"construction"},{"type":"owner","role":"exempt","who":"two-unit property with an owner occupying the second unit for the entire tenancy","unit_limit":2},{"type":"other","text":"Units restricted by a deed, regulatory restriction or recorded document limiting affordability to low- or moderate-income households"},{"type":"other","text":"Units already subject to the City of Los Angeles Rent Stabilization Ordinance"}],"per_tenancy":null,"coverage_quotes":["-Units that were constructed within the last 15 years","-A two-unit property, provided the second unit was occupied by an owner of the property for the entire period of the tenancy.","-Units that are already subject to the City’s RSO."]},"exemptions":"Units constructed within the last 15 years (rolling); units deed-restricted to low- or moderate-income households; certain dormitories; a two-unit property where the owner occupied the second unit; single-family homes and condominiums owned by a natural person with written notice; units already subject to the City’s RSO.","penalty":null,"effective_date":"2024-08-01","valid_through":"2025-07-31","citation":"Cal. Civ. Code § 1947.12","quoted_span":"Annual rent increases are limited to no more than 5% plus the percentage change in the cost of living for the region in which the property is located, or 10% whichever is lower","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
